"""Build the browser-ready acceptance report from retained results, not estimates."""
from pathlib import Path
import collections,datetime,hashlib,html,json,re,shutil
root=Path(__file__).resolve().parent/'evidence/immediate-phase-20261019'
service=root.parents[2]
def read(name):return json.loads((root/name).read_text(encoding='utf-8'))
def log(name):return (root/name).read_text(encoding='utf-8-sig',errors='replace')
def tap(name):
 text=log(name);return {'passed':int(re.findall(r'^# pass (\d+)',text,re.M)[-1]),'failed':int(re.findall(r'^# fail (\d+)',text,re.M)[-1])}
def json_log(name):
 text=log(name)
 for i,c in enumerate(text):
  if c=='{':
   try:return json.JSONDecoder().raw_decode(text[i:])[0]
   except ValueError:pass
 raise ValueError('No JSON evidence: '+name)
def result_suite(title,name,scope):
 rows=read(name)['results'];return {'title':title,'passed':sum(r['status']=='passed' for r in rows),'failed':sum(r['status']=='failed' for r in rows),'artifact':name,'scope':scope}
for source,destination in [('immediate-regression-map.log','service-tests.log'),('immediate-backend-connector.log','backend-connector.log'),('immediate-backend-runner.log','backend-runner.log'),('immediate-quality-settings.log','quality-settings.log'),('immediate-efficiency-transport.log','efficiency-transport.log'),('immediate-frontend-build-merged.log','frontend-build.log')]:shutil.copy2(service/'.local'/source,root/'local'/destination)
